import re

METHODS = {'GET', 'POST', 'PUT', 'DELETE', 'PATCH'}
PERMS = {'ALLOW', 'DENY'}
NL = chr(10)


def norm(p):
    return re.sub('[{][A-Za-z0-9_-]+[}]', '{var}', p)


def segs(p):
    return len([s for s in p.split('/') if s])


def is_prefix(a, b):
    if a == b:
        return True
    return b.startswith(a.rstrip('/') + '/')


def main():
    try:
        with open('/app/input.txt', 'r') as fh:
            raw = fh.read().splitlines()
    except OSError:
        raw = []

    parts = []
    cur = []
    for line in raw:
        if line.strip() == '':
            parts.append(cur)
            cur = []
        else:
            cur.append(line)
    parts.append(cur)

    ep_lines = parts[0] if len(parts) > 0 else []
    be_lines = parts[1] if len(parts) > 1 else []
    plan_lines = [l for grp in parts[2:] for l in grp]

    endpoints = []
    for line in ep_lines:
        f = line.split()
        if len(f) != 4:
            break
        path, m, role, perm = f
        m = m.upper()
        perm = perm.upper()
        if m not in METHODS or perm not in PERMS:
            break
        endpoints.append((path, m, role, perm))

    base = None
    excl = set()
    for line in be_lines:
        f = line.split()
        if not f:
            continue
        kw = f[0].lower()
        if kw == 'base' and len(f) >= 2:
            base = f[1]
        elif kw == 'exclude':
            excl.update(f[1:])

    plan = set()
    for line in plan_lines:
        f = line.split()
        if len(f) != 2:
            break
        p, m = f[0], f[1].upper()
        if m not in METHODS:
            break
        plan.add((norm(p), m))

    if base is not None:
        endpoints = [e for e in endpoints if e[0].startswith(base)]

    canon = {}
    for path, m, role, perm in endpoints:
        n = norm(path)
        if n not in canon:
            canon[n] = path

    uniq = []
    seen = set()
    for path, m, role, perm in endpoints:
        key = (norm(path), m, role)
        if key in seen:
            continue
        seen.add(key)
        uniq.append((norm(path), m, role, perm))

    if not plan:
        chosen = [u for u in uniq if u[2] not in excl]
    else:
        chosen_set = set()
        plan_norms = set(u[0] for u in uniq if (u[0], u[1]) in plan)
        for u in uniq:
            if (u[0], u[1]) in plan and u[2] not in excl:
                chosen_set.add(u)
        all_norms = set(u[0] for u in uniq)
        for pn in all_norms:
            if not any(pn != n and is_prefix(pn, n) for n in plan_norms):
                continue
            group = [u for u in uniq if u[0] == pn]
            nonex = [u for u in group if u[2] not in excl]
            chosen_set.update(nonex if nonex else group)
        chosen = list(chosen_set)

    chosen.sort(key=lambda u: (-segs(u[0]), u[1], u[2], u[3]))
    lines = [canon[u[0]] + ' ' + u[1] + ' ' + u[2] + ' ' + u[3] for u in chosen]
    out = ''.join(l + NL for l in lines) if lines else NL
    with open('/app/output.txt', 'w') as fh:
        fh.write(out)


if __name__ == '__main__':
    main()
